 11→export class JmapClient {
 12→  private session: JmapSession | null = null;
 13→
 14→  constructor(private config: Config["jmap"]) {}
 15→
 16→  /** Bootstrap the JMAP session by fetching the session resource. */
 17→  async connect(): Promise<void> {
 18→    const res = await fetch(this.config.sessionUrl, {
 19→      headers: { Authorization: `Bearer ${this.config.apiToken}` },
 20→    });
 21→
 22→    if (!res.ok) {
 23→      throw new Error(
 24→        `JMAP session bootstrap failed: ${res.status} ${res.statusText}`
 25→      );
 26→    }
 27→
 28→    const data = (await res.json()) as Record<string, unknown>;
 29→
 30→    const primaryAccountId = this.extractPrimaryAccountId(data);
 31→
 32→    this.session = {
 33→      apiUrl: data.apiUrl as string,
 34→      accountId: primaryAccountId,
 35→      uploadUrl: data.uploadUrl as string,
 36→      downloadUrl: data.downloadUrl as string,
 37→    };
 38→  }
 39→
 40→  /** Send a JMAP request and return the response. */
 41→  async request(req: JmapRequest): Promise<JmapResponse> {
 42→    if (!this.session) throw new Error("JMAP client not connected");
 43→
 44→    const res = await fetch(this.session.apiUrl, {
 45→      method: "POST",
 46→      headers: {
 47→        "Content-Type": "application/json",
 48→        Authorization: `Bearer ${this.config.apiToken}`,
 49→      },
 50→      body: JSON.stringify(req),
 51→    });
 52→
 53→    if (!res.ok) {
 54→      throw new Error(`JMAP request failed: ${res.status} ${res.statusText}`);
 55→    }
 56→
 57→    return (await res.json()) as JmapResponse;
 58→  }
 59→
 60→  /**
 61→   * Convenience: send a JMAP request and return the method response
 62→   * matching the given call ID. Throws if JMAP returned an error response.
 63→   */
 64→  async call(
 65→    using: string[],
 66→    methodCalls: JmapRequest["methodCalls"]
 67→  ): Promise<MethodResponse[]> {
 68→    const response = await this.request({ using, methodCalls });
 69→
 70→    for (const [method, args] of response.methodResponses) {
 71→      if (method === "error") {
 72→        const err = args as { type: string; description?: string };
 73→        throw new Error(
 74→          `JMAP error (${err.type}): ${err.description ?? "no description"}`
 75→        );
 76→      }
 77→    }
 78→
 79→    return response.methodResponses;
 80→  }
 81→
 82→  get accountId(): string {
 83→    if (!this.session) throw new Error("JMAP client not connected");
 84→    return this.session.accountId;
 85→  }
 86→
 87→  get downloadUrl(): string {
 88→    if (!this.session) throw new Error("JMAP client not connected");
 89→    return this.session.downloadUrl;
 90→  }
 91→
 92→  get uploadUrl(): string {
 93→    if (!this.session) throw new Error("JMAP client not connected");
 94→    return this.session.uploadUrl;
 95→  }
 96→
 97→  /** Extract the primary mail account ID from the session object. */
 98→  private extractPrimaryAccountId(session: Record<string, unknown>): string {
 99→    const accounts = session.primaryAccounts as
100→      | Record<string, string>
101→      | undefined;
102→    if (accounts) {
103→      const mailAccount = accounts["urn:ietf:params:jmap:mail"];
104→      if (mailAccount) return mailAccount;
105→    }
106→
107→    // Fallback: first key in accounts
108→    const allAccounts = session.accounts as
109→      | Record<string, unknown>
110→      | undefined;
111→    if (allAccounts) {
112→      const firstId = Object.keys(allAccounts)[0];
113→      if (firstId) return firstId;
114→    }
115→
116→    throw new Error(
117→      "Could not determine JMAP account ID from session response"
118→    );
119→  }
120→}
