  9→  private authHeader: string = "";
 10→
 11→  constructor(private config: Config["caldav"]) {}
 12→
 13→  /** Initialize the DAV client and run service discovery. */
 14→  async connect(): Promise<void> {
 15→    this.authHeader =
 16→      "Basic " +
 17→      Buffer.from(`${this.config.username}:${this.config.appPassword}`).toString("base64");
 18→
 19→    this.dav = new DAVClient({
 20→      serverUrl: this.config.url,
 21→      credentials: {
 22→        username: this.config.username,
 23→        password: this.config.appPassword,
 24→      },
 25→      authMethod: "Basic",
 26→      defaultAccountType: "caldav",
 27→    });
 28→
 29→    await this.dav.login();
 30→    this.calendars = await this.dav.fetchCalendars();
 31→  }
 32→
 33→  /** Get the underlying tsdav client. */
 34→  get client(): DAVClient {
 35→    if (!this.dav) throw new Error("CalDAV client not connected");
 36→    return this.dav;
 37→  }
 38→
 39→  /** Get the cached list of calendars (refreshable via fetchCalendars). */
 40→  get cachedCalendars(): DAVCalendar[] {
 41→    return this.calendars;
 42→  }
 43→
 44→  /** Refresh the cached calendar list. */
 45→  async refreshCalendars(): Promise<DAVCalendar[]> {
 46→    if (!this.dav) throw new Error("CalDAV client not connected");
 47→    this.calendars = await this.dav.fetchCalendars();
