 51→  /** PUT an iCalendar object (create or update). */
 52→  async putCalendarObject(
 53→    url: string,
 54→    icalString: string,
 55→    headers?: Record<string, string>
 56→  ): Promise<{ status: number; etag: string }> {
 57→    const res = await fetch(url, {
 58→      method: "PUT",
 59→      headers: {
 60→        Authorization: this.authHeader,
 61→        "Content-Type": "text/calendar; charset=utf-8",
 62→        ...headers,
 63→      },
 64→      body: icalString,
 65→    });
 66→
 67→    if (!res.ok) {
 68→      const body = await res.text();
 69→      throw new Error(`CalDAV PUT failed: ${res.status} ${res.statusText}. ${body}`);
 70→    }
 71→
 72→    return {
 73→      status: res.status,
 74→      etag: res.headers.get("etag")?.replace(/"/g, "") ?? "",
 75→    };
 76→  }
