  3→import ICAL from "ical.js";
  4→
  5→// --- Parsed event shape ---
  6→
  7→export interface ParsedAttendee {
  8→  name: string;
  9→  email: string;
 10→  status: string;
 11→}
 12→
 13→export interface ParsedOrganizer {
 14→  name: string;
 15→  email: string;
 16→}
 17→
 18→export interface ParsedAlarm {
 19→  minutes_before: number;
 20→}
 21→
 22→export interface ParsedEvent {
 23→  uid: string;
 24→  summary: string;
 25→  description: string | null;
 26→  location: string | null;
 27→  start: string; // ISO datetime
 28→  end: string; // ISO datetime
 29→  timezone: string | null;
 30→  allDay: boolean;
 31→  recurrence: string | null;
 32→  attendees: ParsedAttendee[];
 33→  organizer: ParsedOrganizer | null;
 34→  status: string;
 35→  alarms: ParsedAlarm[];
 36→  raw_ical?: string;
 37→}
 38→
 39→// --- Parsing: iCalendar string -> JSON ---
 40→
 41→export function parseEvents(icalString: string): ParsedEvent[] {
 42→  const jcal = ICAL.parse(icalString);
 43→  const comp = new ICAL.Component(jcal);
 44→  const vevents = comp.getAllSubcomponents("vevent");
 45→
 46→  return vevents.map((vevent) => parseVEvent(vevent));
 47→}
 48→
 49→export function parseEvent(icalString: string): ParsedEvent | null {
 50→  const events = parseEvents(icalString);
 51→  return events[0] ?? null;
 52→}
 53→
 54→function parseVEvent(vevent: InstanceType<typeof ICAL.Component>): ParsedEvent {
 55→  const event = new ICAL.Event(vevent);
 56→
 57→  const dtstart = vevent.getFirstProperty("dtstart");
 58→  const timezone = dtstart?.getParameter("tzid") ?? null;
 59→
 60→  return {
 61→    uid: event.uid || "",
 62→    summary: event.summary || "",
 63→    description: event.description || null,
 64→    location: event.location || null,
 65→    start: event.startDate.toJSDate().toISOString(),
 66→    end: event.endDate.toJSDate().toISOString(),
 67→    timezone,
 68→    allDay: event.startDate.isDate,
 69→    recurrence: parseRecurrence(vevent),
 70→    attendees: parseAttendees(vevent),
 71→    organizer: parseOrganizer(vevent),
 72→    status: event.status || "CONFIRMED",
 73→    alarms: parseAlarms(vevent),
 74→  };
 75→}
 76→
 77→function parseRecurrence(
 78→  vevent: InstanceType<typeof ICAL.Component>
 79→): string | null {
 80→  const rrule = vevent.getFirstPropertyValue("rrule");
 81→  if (!rrule) return null;
 82→  return rrule.toString();
 83→}
 84→
 85→function parseAttendees(
 86→  vevent: InstanceType<typeof ICAL.Component>
 87→): ParsedAttendee[] {
 88→  const props = vevent.getAllProperties("attendee");
 89→  return props.map((prop) => {
 90→    const val = (prop.getFirstValue() as string) || "";
 91→    const email = val.replace(/^mailto:/i, "");
 92→    const name = prop.getParameter("cn") || email;
 93→    const status = prop.getParameter("partstat") || "NEEDS-ACTION";
 94→    return { name, email, status };
 95→  });
 96→}
 97→
 98→function parseOrganizer(
 99→  vevent: InstanceType<typeof ICAL.Component>
100→): ParsedOrganizer | null {
101→  const prop = vevent.getFirstProperty("organizer");
102→  if (!prop) return null;
103→  const val = (prop.getFirstValue() as string) || "";
104→  const email = val.replace(/^mailto:/i, "");
105→  const name = prop.getParameter("cn") || email;
106→  return { name, email };
107→}
108→
109→function parseAlarms(
110→  vevent: InstanceType<typeof ICAL.Component>
111→): ParsedAlarm[] {
112→  const valarms = vevent.getAllSubcomponents("valarm");
113→  return valarms
114→    .map((valarm) => {
115→      const trigger = valarm.getFirstPropertyValue("trigger");
116→      if (!trigger) return null;
117→      const dur = trigger as InstanceType<typeof ICAL.Duration>;
118→      if (typeof dur.toSeconds !== "function") return null;
119→      const seconds = dur.toSeconds();
120→      // Negative duration = before event start
121→      const minutes = Math.abs(Math.round(seconds / 60));
122→      return { minutes_before: minutes };
123→    })
124→    .filter((a): a is ParsedAlarm => a !== null);
125→}
